<script setup>
import { computed } from 'vue'
import Icon from './Icon.vue'
import Art from './Art.vue'
import { lkr } from './rules'
const props=defineProps({data:Object,member:Object})
defineEmits(['navigate','room','create','video'])
const admin=computed(()=>props.member.role==='Admin')
const maxRevenue=computed(()=>Math.max(1,...props.data.revenue.map(r=>r.amount)))
</script>
<template>
  <div class="page-heading"><div><div class="eyebrow">{{admin?'YOUR INSTITUTE, AT A GLANCE':'A LITTLE INSPIRATION. A BIG DIFFERENCE.'}}</div><h1>{{admin?'A brighter campus starts here.':'Hello, '+member.full_name.split(' ')[0]+'.'}} <span class="greeting-spark">✺</span></h1><p>{{admin?'Students, teachers and every little milestone. Together in one place.':'Your classes, your community, your next chapter.'}}</p></div><button class="button primary" @click="$emit('create',admin?'member':'session')"><Icon :name="admin?'UserPlus':'Plus'" :size="17"/>{{admin?'Register a student':'Schedule a class'}}</button></div>
  <section class="insight-hero"><div><span class="hero-label">SISU LANKA · FICTIONAL DEMO ACADEMY</span><h2>{{admin?'Small steps.\nExtraordinary futures.':'Good teaching deserves\na bigger audience.'}}</h2><p>{{admin?'Five learning pathways. One connected community.':'Turn curiosity into your next classroom. Build a campaign, invite enquiries and welcome new learners.'}}</p><button class="button dark" @click="$emit('navigate',admin?'people':'marketing')">{{admin?'Meet your community':'Open marketing studio'}} <Icon name="ArrowRight" :size="16"/></button></div><Art/></section>
  <div class="insight-stats"><button @click="$emit('navigate','people')"><span class="stat-icon violet"><Icon name="Users"/></span><strong>{{data.totals.students}}</strong><small>{{admin?'Active students':'My students'}}</small></button><button @click="$emit('navigate',admin?'teachers':'classrooms')"><span class="stat-icon peach"><Icon name="GraduationCap"/></span><strong>{{admin?data.totals.teachers:data.totals.classes}}</strong><small>{{admin?'Registered teachers':'My classrooms'}}</small></button><button @click="$emit('navigate','payments')"><span class="stat-icon mint"><Icon name="Wallet"/></span><strong>{{lkr(data.totals.collected)}}</strong><small>Collected · {{data.month}}</small></button><button @click="$emit('navigate','competition')"><span class="stat-icon violet"><Icon name="Award"/></span><strong>{{data.totals.completion}}%</strong><small>This month’s learning completion</small></button></div>
  <div class="insight-grid"><section class="panel"><div class="section-heading"><div><h2>{{admin?'Learning across your campus':'Your classroom pulse'}}</h2><p>{{data.totals.classes}} classrooms · {{data.totals.progress}}% overall lesson completion</p></div><Icon name="BookOpen"/></div><div v-for="c in data.categories" :key="c.name" class="category-meter"><div><strong>{{c.name}}</strong><span>{{c.students}} students · {{c.classes}} classes</span></div><div class="meter-track"><i :style="{width:Math.max(4,c.students/data.totals.students*100)+'%'}"></i></div></div><button class="text-button" @click="$emit('navigate','classrooms')">Explore classrooms <Icon name="ArrowRight" :size="15"/></button></section>
