  <section class="challenge-card"><span class="stat-icon white"><Icon name="Award" :size="28"/></span><span class="eyebrow">THIS MONTH’S LEARNING CHALLENGE</span><h2>A little practice.<br>A reason to celebrate.</h2><p>{{data.leaderboard.length}} demo learners · Quiz practice, lesson completion and attendance.</p><div class="podium-mini"><span v-for="s in data.leaderboard.slice(0,3)" :key="s.student"><b>#{{s.rank}}</b>{{s.alias}}<strong>{{s.score}} pts</strong></span></div><button class="button dark" @click="$emit('navigate','competition')">View monthly challenge <Icon name="ArrowRight" :size="16"/></button></section></div>
  <button class="video-teaser" @click="$emit('video')"><span class="video-play"><Icon name="Play" :size="24"/></span><div><span class="eyebrow">YOUR YOUTUBE EXAMPLE IS HERE</span><h3>Step inside the classroom.</h3><p>Play the supplied video right here in your LMS.</p></div><Icon name="ArrowUpRight"/></button>
</template>
